package com.gamehub.application;
import com.gamehub.infrastructure.Database; import java.sql.*; import java.time.*; import java.util.*;
public final class OperationsService {
 private final Database db; public OperationsService(Database db){this.db=db;}
 public long addStation(String code,String type,long hourlyPaisa)throws SQLException{if(code.isBlank()||hourlyPaisa<=0)throw new IllegalArgumentException("Station code/type/rate are required");try(var p=db.connection().prepareStatement("INSERT INTO gaming_stations(code,type,hourly_rate_paisa,status) VALUES(?,?,?,'AVAILABLE')",Statement.RETURN_GENERATED_KEYS)){p.setString(1,code);p.setString(2,type);p.setLong(3,hourlyPaisa);p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public List<String> stations()throws SQLException{List<String> out=new ArrayList<>();try(var s=db.connection().createStatement();var r=s.executeQuery("SELECT code,type,status,hourly_rate_paisa FROM gaming_stations ORDER BY code")){while(r.next())out.add(r.getString(1)+" | "+r.getString(2)+" | "+r.getString(3)+" | PKR "+(r.getLong(4)/100.0));}return out;}
 public long reserve(long userId,long stationId,Instant start,Instant end)throws SQLException{if(!start.isBefore(end))throw new IllegalArgumentException("Start must precede end");String q="SELECT COUNT(*) FROM reservations WHERE station_id=? AND status='CONFIRMED' AND starts_at<? AND ends_at>?";try(var p=db.connection().prepareStatement(q)){p.setLong(1,stationId);p.setString(2,end.toString());p.setString(3,start.toString());try(var r=p.executeQuery()){if(r.next()&&r.getInt(1)>0)throw new IllegalStateException("Station is already reserved");}}try(var p=db.connection().prepareStatement("INSERT INTO reservations(user_id,station_id,starts_at,ends_at,status) VALUES(?,?,?,?,'CONFIRMED')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,userId);p.setLong(2,stationId);p.setString(3,start.toString());p.setString(4,end.toString());p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public long startSession(long reservationId)throws SQLException{try(var p=db.connection().prepareStatement("INSERT INTO sessions(reservation_id,started_at,status) VALUES(?,?,'ACTIVE')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,reservationId);p.setString(2,Instant.now().toString());p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public long finishSession(long sessionId,long chargePaisa)throws SQLException{if(chargePaisa<0)throw new IllegalArgumentException("Charge cannot be negative");try(var p=db.connection().prepareStatement("UPDATE sessions SET ended_at=?,status='COMPLETED',charge_paisa=? WHERE id=?")){p.setString(1,Instant.now().toString());p.setLong(2,chargePaisa);p.setLong(3,sessionId);if(p.executeUpdate()!=1)throw new IllegalArgumentException("Session not found");return sessionId;}}
 public long recordPayment(long userId,long amountPaisa,String method,String reference)throws SQLException{if(amountPaisa<=0||method.isBlank())throw new IllegalArgumentException("Valid payment is required");try(var p=db.connection().prepareStatement("INSERT INTO payments(user_id,amount_paisa,method,reference,status,created_at) VALUES(?,?,?,?,'SETTLED',?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,userId);p.setLong(2,amountPaisa);p.setString(3,method);p.setString(4,reference);p.setString(5,Instant.now().toString());p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public long reportCount(String table)throws SQLException{if(!Set.of("users","gaming_stations","reservations","sessions","payments","teams","tournaments","maintenance").contains(table))throw new IllegalArgumentException("Unsupported report");try(var s=db.connection().createStatement();var r=s.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getLong(1);}}
}
